import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"回复生日派对邀请","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/02-birthday-reply.md","filePath":"zh/more/maltese/practice/emails/02-birthday-reply.md"}'),e={name:"zh/more/maltese/practice/emails/02-birthday-reply.md"},o=r('<h1 id="回复生日派对邀请" tabindex="-1">回复生日派对邀请 <a class="header-anchor" href="#回复生日派对邀请" aria-label="Permalink to &quot;回复生日派对邀请&quot;">​</a></h1><p><strong>场景：</strong> Mark 回复 Anna，接受生日派对邀请并询问是否需要帮忙。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Mingħand（发件人 From）：</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Data（日期）：</strong> 12 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Risposta għall-istedina</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Data:</strong> 12 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Risposta għall-istedina</p><p>Għażiża Anna,</p><p>Grazzi ħafna tal-istedina.</p><p>Iva, nixtieq niġi għall-festa nhar is-Sibt.</p><p>Se nkun hemm fis-sebgħa.</p><p>Nista&#39; nġib xi ħaġa miegħi?</p><p>Nista&#39; nġib kejk żgħir.</p><p>Għidli jekk għandek bżonn l-għajnuna.</p><p>Nistenna bil-ħerqa li narak.</p><p>Tislijiet, Mark</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>整句：</strong> 收件人（To）：anna.c@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>邮箱地址</td><td>收件人（Anna）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></p><p><strong>整句：</strong> 发件人（From）：mark.b@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td><a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></td><td>邮箱地址</td><td>发件人（Mark）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 12 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 12 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>12</td><td>十二</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Risposta għall-istedina</p><p><strong>整句：</strong> 主题：回复邀请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Risposta</td><td>回复；答复</td><td>阴性名词</td></tr><tr><td>għall-istedina</td><td>针对邀请；回应邀请</td><td><code>għal</code> + <code>l-istedina</code> 的缩合形式</td></tr></tbody></table><p><strong>Malti:</strong> Għażiża Anna,</p><p><strong>整句：</strong> 亲爱的安娜：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiża</td><td>亲爱的</td><td>阴性单数形式，用于称呼女性</td></tr><tr><td>Anna</td><td>安娜</td><td>人名</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi ħafna tal-istedina.</p><p><strong>整句：</strong> 非常感谢你的邀请。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>ħafna</td><td>很；非常</td><td>程度副词</td></tr><tr><td>tal-istedina</td><td>邀请的；因为邀请</td><td><code>ta&#39; + l-istedina</code> 的缩合形式</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Iva, nixtieq niġi għall-festa nhar is-Sibt.</p><p><strong>整句：</strong> 好的，我愿意星期六来参加派对。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Iva</td><td>是；好的</td><td>肯定回答</td></tr><tr><td>nixtieq</td><td>我想；我愿意</td><td>礼貌表达愿望</td></tr><tr><td>niġi</td><td>我来</td><td>第一人称单数形式</td></tr><tr><td>għall-festa</td><td>去派对；参加派对</td><td><code>għal</code> + <code>il-festa</code> 的缩合形式</td></tr><tr><td>nhar</td><td>在……那天</td><td>引出星期/日期</td></tr><tr><td>is-Sibt</td><td>星期六</td><td>星期名称带定冠词</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Se nkun hemm fis-sebgħa.</p><p><strong>整句：</strong> 我会在七点到那里。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>将来标记</td></tr><tr><td>nkun</td><td>我会是；我会在</td><td>第一人称单数形式</td></tr><tr><td>hemm</td><td>那里；在场</td><td>地点副词</td></tr><tr><td>fis-sebgħa</td><td>在七点</td><td><code>f&#39;</code> + 定冠词钟点形式缩合</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; nġib xi ħaġa miegħi?</p><p><strong>整句：</strong> 我可以带点东西来吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>我可以吗</td><td>第一人称单数形式</td></tr><tr><td>nġib</td><td>我带来</td><td>第一人称单数形式</td></tr><tr><td>xi</td><td>一些；某个</td><td>不定限定词</td></tr><tr><td>ħaġa</td><td>东西</td><td>阴性名词</td></tr><tr><td>miegħi</td><td>和我一起；随身</td><td><code>miegħ</code>“和” + <code>-i</code>“我”</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; nġib kejk żgħir.</p><p><strong>整句：</strong> 我可以带一个小蛋糕。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>我可以</td><td>第一人称单数形式</td></tr><tr><td>nġib</td><td>我带来</td><td>第一人称单数形式</td></tr><tr><td>kejk</td><td>蛋糕</td><td>阳性名词</td></tr><tr><td>żgħir</td><td>小的</td><td>阳性单数形式，与 <code>kejk</code> 一致</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Għidli jekk għandek bżonn l-għajnuna.</p><p><strong>整句：</strong> 如果你需要帮忙，请告诉我。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għidli</td><td>告诉我</td><td><code>għid</code>“说/告诉” + <code>-li</code>“我”</td></tr><tr><td>jekk</td><td>如果</td><td>连词</td></tr><tr><td>għandek</td><td>你有</td><td><code>għand</code> 的第二人称单数形式</td></tr><tr><td>bżonn</td><td>需要</td><td><code>għandek bżonn</code> 表示“你需要”</td></tr><tr><td>l-għajnuna</td><td>帮助</td><td>阴性名词，带定冠词</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Nistenna bil-ħerqa li narak.</p><p><strong>整句：</strong> 我期待见到你。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nistenna</td><td>我等待；我期待</td><td>第一人称单数形式</td></tr><tr><td>bil-ħerqa</td><td>热切地；期待地</td><td>固定副词短语</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>narak</td><td>我见到你</td><td><code>nara</code>“我看见” + <code>-k</code>“你”</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, Mark</p><p><strong>整句：</strong> 此致敬意，马克（邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Mark</td><td>马克</td><td>人名</td></tr></tbody></table>',53),n=[o];function i(l,h,s,g,b,c){return d(),a("div",null,n)}const k=t(e,[["render",i]]);export{m as __pageData,k as default};
